    const expected = (n / 60n) + 'm ' + (n % 60n) + 's'
    assert.equal(formatDuration(s), expected)
  }

  // Re-run invalid input checks
  const invalidInputs = [Number.MAX_SAFE_INTEGER + 1, -1, 1.5, NaN, Infinity, '60', null, undefined, {}, 60n]
