    assert.throws(() => formatDuration(s), RangeError)
  }
})

// Test 2: Preserve existing stock.js behavior and orderBoxes validation from examples.test.js
test('stock.js remains byte-identical in behavior and validates inputs correctly', () => {
  const { orderBoxes } = require('../src/localBrain/examples/stock.js')
  // Re-run original stock test cases
  assert.equal(orderBoxes(3, 10, 4), 2)
  assert.equal(orderBoxes(0.1, 0.4, 0.1), 3)
  assert.equal(orderBoxes(0, 1.1, 0.1), 11)
  assert.equal(orderBoxes(1.01, 1.04, 0.01), 3)
  assert.equal(orderBoxes(12, 10, 4), 0)

  // Re-run invalid input checks for stock.js
  const invalidValues = [NaN, Infinity, -Infinity, '2', undefined, null, true, {}, []]
  for (const v of invalidValues) {
